def transform_mid(g):
    """3-line world implicit: each row/col with >=2 blues; light full line but stops at unconverted blocks;
    block converts iff it is an EDGE block (first/last) on EVERY line that crosses it"""
    h,w=len(g),len(g[0]); B=find_blues(g); bl=blocks_of(g)
    rows=[i for i in range(h) if sum(1 for (a,b) in B if a==i)>=2]
    cols=[j for j in range(w) if sum(1 for (a,b) in B if b==j)>=2]
    lines=[('r',i) for i in rows]+[('c',j) for j in cols]
    def blocks_on(ax,idx):
        if ax=='r': return sorted([blk for blk in bl if blk[0]<=idx<=blk[2]], key=lambda b:b[1])
        return sorted([blk for blk in bl if blk[1]<=idx<=blk[3]], key=lambda b:b[0])
    def is_edge(blk,ax,idx):
        bs=blocks_on(ax,idx); n=len(bs)
        return blk in (bs[0],bs[-1]) if n>1 else True
    conv={blk for blk in bl
          if all(is_edge(blk,ax,idx) for ax,idx in lines if line_crosses(blk,ax,idx))}
    # a block is crossed by a line if line passes through it
    return conv

def line_crosses(blk,ax,idx):
    r0,c0,r1,c1=blk
    return (r0<=idx<=r1) if ax=='c' else (c0<=idx<=c1)

def render(g,conv):
