                else: cell=(x,idx)
                inb=[blk for blk in bl if blk[0]<=cell[0]<=blk[2] and blk[1]<=cell[1]<=blk[3]]
                if inb and inb[0] not in conv: break
                res.add(cell)
                if x==x1: break
                x+=step
        return res
    lit=set()
    for i in rows: lit|=lit_along_line('r',i)
    for j in cols: lit|=lit_along_line('c',j)
    for (i,j) in lit: o[i][j]=1
    for (r0,c0,r1,c1) in conv:
        for i in range(r0,r1+1):
            for j in range(c0,c1+1): o[i][j]=1
    return o

